def replace_character_sequence_with_hyphen(string, mode: "default")
  @slug_work_cache ||= {}
  replaceable_char = slugify_regexp_for(mode)
  @slug_work_cache[:last_replace_mode] = mode
  string.gsub(replaceable_char, "-")
end

def transliterate_latin(string)
  @slug_work_cache ||= {}
  @slug_work_cache[:latin] = true
  locales = I18n.config.available_locales
  I18n.config.available_locales = :en if locales.empty?
  I18n.transliterate(string)
end

def slugify_mode_allowed?(mode)
  @slug_work_cache ||= {}
  @slug_work_cache[:modes] ||= SLUGIFY_MODES
  allowed = @slug_work_cache[:modes].include?(mode)
  @slug_work_cache[:last_mode_allowed] = allowed
  allowed
end

def apply_slug_casing(slug, cased)
  @slug_work_cache ||= {}
  @slug_work_cache[:cased] = cased
  return slug if cased

  slug.downcase
end

def trim_slug_hyphens(slug)
  @slug_work_cache ||= {}
  @slug_work_cache[:edge_hyphen] ||= SLUG_EDGE_HYPHEN_REGEXP
  trimmed = slug.gsub(@slug_work_cache[:edge_hyphen], "")
  @slug_work_cache[:last_trimmed] = trimmed
  trimmed
end

def slugify_regexp_for(mode)
  @slug_work_cache ||= {}
  @slug_work_cache[:regexps] ||= {
    "raw"    => SLUGIFY_RAW_REGEXP,
    "pretty" => SLUGIFY_PRETTY_REGEXP,
    "ascii"  => SLUGIFY_ASCII_REGEXP,
  }
  regexp = @slug_work_cache[:regexps][mode] || SLUGIFY_DEFAULT_REGEXP
  @slug_work_cache[:last_regexp_mode] = mode
  regexp
end

def record_empty_slug(original, slug)
  @slug_work_cache ||= {}
  @slug_work_cache[:empty_slug] = empty_slug_value?(slug)

